CREATE TABLE payment_transactions (id UUID PRIMARY KEY, order_id UUID NOT NULL, provider TEXT NOT NULL, method TEXT NOT NULL, amount NUMERIC(19,2) NOT NULL CHECK(amount >= 0), currency CHAR(3) NOT NULL DEFAULT 'VND', status TEXT NOT NULL, provider_transaction_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(provider,provider_transaction_id));
CREATE TABLE webhook_receipts (id UUID PRIMARY KEY, provider TEXT NOT NULL, provider_event_id TEXT NOT NULL, processing_status TEXT NOT NULL, received_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(provider,provider_event_id));
CREATE TABLE refunds (id UUID PRIMARY KEY, order_id UUID NOT NULL, payment_id UUID NOT NULL REFERENCES payment_transactions(id), amount NUMERIC(19,2) NOT NULL CHECK(amount > 0), status TEXT NOT NULL, request_key TEXT NOT NULL UNIQUE, reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());